#!/usr/bin/env bash
# Build every Chrome Web Store asset into dist/store/.
#
#   store-icon-128.png            required
#   promo-tile-440x280.png        required for the listing
#   screenshot-1-what-it-does.png 1280x800
#   screenshot-2-settings.png     1280x800
#
# The screenshots are generated by running the real extension against
# tests/fixtures/demo.html, so the "before" and "after" are the same page at the
# same moment and the listing cannot drift from what the extension does.
set -euo pipefail

cd "$(dirname "$0")/.."
OUT=dist/store
BG='#171B2B'
PANEL='#2A3145'
INK='#F4F6FB'
MUTED='#AEB8CC'

for tool in rsvg-convert magick; do
  command -v "$tool" >/dev/null || { echo "missing $tool (brew install librsvg imagemagick)" >&2; exit 1; }
done

# Raw material: three real screenshots from a real capture. SKIP_SHOTS=1 reuses
# what is already in dist/store, which is only for iterating on the layout.
if [ "${SKIP_SHOTS:-0}" = "1" ] && [ -f "$OUT/raw-fullpage.png" ]; then
  echo "reusing existing raw screenshots (SKIP_SHOTS=1)"
else
  node scripts/store-shots.mjs
fi

# --- fixed-size assets ---------------------------------------------------
cp icons/tile128.png "$OUT/store-icon-128.png"
rsvg-convert -w 440 -h 280 assets/promo-tile.svg -o "$OUT/promo-tile-440x280.png"

# --- screenshot 1: what it does ------------------------------------------
# The viewport beside the full-page capture taken from it. Both panels start on
# the same baseline, so the only difference the eye has to read is the height.
magick "$OUT/raw-viewport.png" -resize 700x -bordercolor "$PANEL" -border 1 "$OUT/.v.png"
magick "$OUT/raw-fullpage.png" -resize x540 -bordercolor "$PANEL" -border 1 "$OUT/.f.png"

# Captions carry the real CSS dimensions of the real capture, halved out of the
# 2x device pixels the rig shoots at. A listing that rounds this is a listing
# that will not match what the user gets.
FULL_W=$(( $(magick identify -format '%w' "$OUT/raw-fullpage.png") / 2 ))
FULL_H=$(( $(magick identify -format '%h' "$OUT/raw-fullpage.png") / 2 ))
F_W=$(magick identify -format '%w' "$OUT/.f.png")
F_X=$(( 1280 - 72 - F_W ))

magick -size 1280x800 "xc:$BG" \
  -font Helvetica-Bold -pointsize 44 -fill "$INK" -annotate +72+92 'The whole page, one image' \
  -font Helvetica -pointsize 21 -fill "$MUTED" -annotate +72+132 'One keystroke. Sticky headers appear once. No account, no telemetry.' \
  -font Helvetica-Bold -pointsize 18 -fill "$MUTED" -annotate +72+196 'WHAT YOU SEE' \
  -font Helvetica-Bold -pointsize 18 -fill '#4C8DFF' -annotate "+${F_X}+196" 'WHAT YOU GET' \
  \( "$OUT/.v.png" \) -geometry +72+212 -composite \
  \( "$OUT/.f.png" \) -geometry "+${F_X}+212" -composite \
  -font Helvetica -pointsize 17 -fill "$MUTED" -annotate +72+686 "The visible viewport, 1280 x 800" \
  -font Helvetica -pointsize 17 -fill "$MUTED" -annotate "+${F_X}+782" "One PNG, ${FULL_W} x ${FULL_H}" \
  "$OUT/screenshot-1-what-it-does.png"

# --- screenshot 2: the settings page -------------------------------------
# Captured at 2x, so this is a clean halving rather than a resample.
magick "$OUT/raw-options.png" -resize 1280x800 "$OUT/screenshot-2-settings.png"

rm -f "$OUT/.v.png" "$OUT/.f.png"

echo
echo "dist/store:"
for f in "$OUT"/*.png; do
  case "$f" in */raw-*) continue;; esac
  printf '  %-34s %s\n' "$(basename "$f")" \
    "$(magick identify -format '%wx%h' "$f")"
done
